require_once __DIR__.'/config.php'; if(logged_in())redirect('index.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');$email=strtolower(trim($_POST['email']??''));$password=(string)($_POST['password']??'');$license=trim($_POST['license_no']??'');$birth=$_POST['birth_date']??'';$sex=$_POST['sex']??'';$club=($_POST['club_id']??'')!==''?(int)$_POST['club_id']:null;
 if(!$first||!$last||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10||!$license||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birth)||!in_array($sex,['F','M'],true))$error='Vérifiez les champs. Le mot de passe doit contenir au moins 10 caractères.';
 else{try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO swimmers(license_no,first_name,last_name,birth_date,sex,club_id) VALUES(?,?,?,?,?,?)');$q->execute([$license,$first,$last,$birth,$sex,$club]);$sid=(int)$pdo->lastInsertId();if($club){$pdo->prepare('INSERT INTO swimmer_club_history(swimmer_id,club_id,joined_on) VALUES(?,?,CURDATE())')->execute([$sid,$club]);}$q=$pdo->prepare('INSERT INTO users(name,email,password,role,club_id,swimmer_id) VALUES(?,?,?,\'nageur\',?,?)');$q->execute([$first.' '.$last,$email,password_hash($password,PASSWORD_DEFAULT),$club,$sid]);$uid=(int)$pdo->lastInsertId();$pdo->commit();session_regenerate_id(true);$_SESSION['user']=['id'=>$uid,'name'=>$first.' '.$last,'email'=>$email,'role'=>'nageur','club_id'=>$club,'swimmer_id'=>$sid];redirect('index.php');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error='Inscription impossible : cette adresse e-mail ou ce numéro de licence existe peut-être déjà.';}}
}
$clubs=[];try{$clubs=db()->query('SELECT id,name,city FROM clubs ORDER BY name')->fetchAll();}catch(Throwable $e){}
?>
